"""Compile the reviewed Fortinet FG-60F Ethernet-only model for SQL20; prior catalogs are frozen."""
from __future__ import annotations
import argparse
import importlib.util
import json
import os
from pathlib import Path
import sys
import tempfile
ROOT = Path(__file__).absolute().parents[1]
_spec = importlib.util.spec_from_file_location('hardware_catalog_helpers20', ROOT/'tools/build_hardware_catalog19.py')
g = importlib.util.module_from_spec(_spec); _spec.loader.exec_module(g)
c = g.c
SOURCE='development/hardware/catalog-fortinet-v1.json'
FACTS='development/hardware/fortinet-fg60f.facts.json'
LOCK='development/hardware/catalog-schema20.lock.json'
BASE='development/server/database/019-aruba-hardware.sql'
SERVER='development/server/src/RackClick.Server/FortinetHardwareProfiles.Generated.cs'
FRONTEND='development/frontend/src/hardware-fortinet.generated.json'
SQL='development/server/database/020-fortinet-hardware.sql'
MANIFEST='development/hardware/catalog-fortinet.manifest.json'
TARGETS='development/server/src/RackClick.Server/FortinetHardware.Generated.targets'
STATE='curated_development_not_a_release'
EXPECTED_SOURCE=json.loads('{"catalogKey":"rackclick-fortinet-01","definitions":[{"color":"#e9e9e6","dimensionsMm":{"depth":160,"height":38.5,"width":216},"groups":[{"count":5,"face":"rear","key":"rear-lan","name":"LAN","powerRole":"unspecified","prefix":"","type":"rj45"},{"count":2,"face":"rear","key":"rear-fortilink","name":"FortiLink","powerRole":"unspecified","prefix":"FortiLink ","type":"rj45"},{"count":1,"face":"rear","key":"rear-dmz","name":"DMZ","powerRole":"unspecified","prefix":"DMZ ","type":"rj45"},{"count":2,"face":"rear","key":"rear-wan","name":"WAN","powerRole":"unspecified","prefix":"WAN ","type":"rj45"}],"identity":{"family":"FortiGate 60F Series","manufacturer":"Fortinet","model":"FortiGate 60F","sku":"FG-60F"},"key":"fortinet-fg60f","kind":"desktop","passthrough":null,"provenance":{"assets":[],"kind":"manufacturer-specification","source":"https://www.fortinet.com/content/dam/fortinet/assets/data-sheets/pdf/fortigate-fortiwifi-60f-series.pdf"},"rackUnits":0,"revision":"fortinet-20261030-v1","slots":[]}],"formatVersion":1}')
EXPECTED_FACTS=json.loads('{"facts":{"connectableEthernetPorts":10,"depthMm":160,"fanless":true,"formFactor":"desktop","heightMm":38.5,"poe":false,"rackUnitsAdditional":0,"rearDmz":1,"rearFortiLink":2,"rearLan":5,"rearWan":2,"widthMm":216},"formatVersion":1,"geometry":"Own flat interactive drawing; no manufacturer photograph embedded","hardwareRevision":null,"locators":{"dimensions":"Pinned official PDF page8 Dimensions:HeightxWidthxLength38.5x216x160mm; FormFactorDesktop.","ports":"Pinned official PDF page8 HardwareSpecifications:WAN/DMZ2/1,Internal5,FortiLink2,Console1,USB1; exactFG60F front/rear page7.","power":"Pinned official PDF page9 PowerRating12Vdc3A; externalDCadapter100-240VAC; fanless0dBA."},"model":"FG-60F","nonConnectableReferences":{"consoleRj45":1,"dcInput":{"maxAmps":3,"reason":"Generic power inlet/outlet cannot validate AC/DC, polarity or adapter compatibility; no DC inventory port in this revision.","supply":"external AC/DC adapter","volts":12},"usb":1},"pdfSha256":"77a97c99e5e800837dc7eed4551c485d95e9822f60b4782bf97f90597a4eabc6","releaseDate":null,"retrieved":"2026-10-30","scope":"Ethernet-only profile. Console RJ45 is not Ethernet; USB and DC are noninteractive references pending separate contracts. External adapter is not a modeled device.","url":"https://www.fortinet.com/content/dam/fortinet/assets/data-sheets/pdf/fortigate-fortiwifi-60f-series.pdf"}')

pretty = g.pretty
literal = g.literal

def sql_source(model,digest):
    lines=['-- Auto-generated by tools/build_hardware_catalog20.py; SQL001-019 are frozen.',
      '-- Ethernet-only desktop profile: no DC, USB, console port or adapter semantics.',
      '-- Existing sealing/publication triggers and runtime grants remain unchanged.']
    def insert(table,columns,values):lines.append('INSERT INTO '+table+' ('+columns+') VALUES ('+', '.join(map(literal,values))+');')
    pair=[model['key'],model['revision']];d=model['dimensionsMm']
    insert('hardware_definition','profile_key, revision, mount_kind, rack_units, width_mm, height_mm, depth_mm, color, definition_sha256, manufacturer, family, model, sku, provenance_kind, source_reference, sealed',pair+[model['kind'],model['rackUnits'],d['width'],d['height'],d['depth'],model['color'],digest]+[model['identity'][key] for key in ('manufacturer','family','model','sku')]+[model['provenance']['kind'],model['provenance']['source'],False])
    for order,g in enumerate(model['groups']):
        insert('hardware_group_template','profile_key, revision, group_key, sort_order, type, port_count, face, name, prefix, power_role',pair+[g['key'],order,g['type'],g['count'],g['face'],g['name'],g['prefix'],g['powerRole']])
    lines.append('UPDATE hardware_definition SET sealed=true WHERE profile_key='+literal(pair[0])+' AND revision='+literal(pair[1])+';')
    return ('\n'.join(lines)+'\n').encode('utf-8')

def targets_source(inputs):
    return (g.targets_source(inputs).decode('ascii')
        .replace('build_hardware_catalog19.py','build_hardware_catalog20.py')
        .replace('Aruba','Fortinet').replace('aruba_catalog','fortinet_catalog')).encode('ascii')

def compile_catalog(root):
    raw={name:c.path(root,name).read_bytes() for name in (SOURCE,FACTS,LOCK,BASE)}
    source=c.load(raw[SOURCE]);facts=c.load(raw[FACTS]);lock=c.load(raw[LOCK])
    c.fields(lock,'formatVersion targetSchema sourceSha256 factsSha256 baseMigrationSha256 definitions state','fortinet_lock_invalid')
    c.require(type(lock['formatVersion']) is int and lock['formatVersion']==1 and type(lock['targetSchema']) is int and lock['targetSchema']==20 and lock['state']==STATE,'fortinet_target_unsupported')
    for name,field in ((SOURCE,'sourceSha256'),(FACTS,'factsSha256'),(BASE,'baseMigrationSha256')):c.require(c.sha(raw[name])==lock[field],'fortinet_input_changed')
    # Narrow publication profile: repinning a new model/role/source is not review.
    c.require(c.canonical(source)==c.canonical(EXPECTED_SOURCE),'fortinet_model_not_reviewed')
    c.require(c.canonical(facts)==c.canonical(EXPECTED_FACTS),'fortinet_facts_mismatch')
    model=source['definitions'][0];pins=[dict(key=model['key'],revision=model['revision'],sha256=c.sha(c.canonical(model)))]
    c.require(lock['definitions']==pins,'fortinet_definition_not_reviewed')
    server=c.server_source(source,commercial=True).decode('ascii').replace('tools/build_hardware_catalog.py;','tools/build_hardware_catalog20.py;').replace('internal static class CommercialHardwareProfiles','internal static class FortinetHardwareProfiles')
    view=c.projection(source);view['synthetic']=False
    for row,m in zip(view['profiles'],source['definitions']):
        row.update(identity=m['identity'],source=m['provenance']['source'])
        for g,original in zip(row['groups'],m['groups']):g['powerRole']=original['powerRole']
    outputs={SERVER:server.encode('ascii'),FRONTEND:pretty(view),SQL:sql_source(model,pins[0]['sha256'])}
    inputs={name:c.sha(value) for name,value in raw.items()}
    outputs[MANIFEST]=pretty(dict(formatVersion=1,targetSchema=20,catalogKey=source['catalogKey'],state=STATE,inputs=inputs,files={name:c.sha(value) for name,value in outputs.items()},definitions=pins))
    outputs[TARGETS]=targets_source({**inputs,**{name:c.sha(value) for name,value in outputs.items()}})
    return outputs

def run(root,write=False):
    outputs=compile_catalog(root);targets={name:c.path(root,name) for name in outputs}
    for target in targets.values():
        c.require(not target.exists() or target.is_file(),'fortinet_output_invalid')
        c.require(all(not p.exists() or p.is_dir() for p in target.parents),'fortinet_output_invalid')
    if write:
        staged={}
        try:
            for name,target in targets.items():
                target.parent.mkdir(parents=True,exist_ok=True);fd,temporary=tempfile.mkstemp(prefix='.catalog20-',dir=target.parent);staged[name]=temporary
                with os.fdopen(fd,'wb') as stream:stream.write(outputs[name]);stream.flush();os.fsync(stream.fileno())
            for name,target in targets.items():os.replace(staged[name],target)
        finally:
            for temporary in staged.values():
                if os.path.lexists(temporary):os.unlink(temporary)
    else:
        for name,target in targets.items():c.require(target.is_file() and target.read_bytes()==outputs[name],'fortinet_catalog_stale')
    return dict(status='written' if write else 'verified',targetSchema=20,definitions=1,files={name:c.sha(value) for name,value in outputs.items()},databaseChanged=False)

def main():
    parser=argparse.ArgumentParser(description=__doc__);mode=parser.add_mutually_exclusive_group(required=True);mode.add_argument('--check',action='store_true');mode.add_argument('--write',action='store_true');args=parser.parse_args()
    try:print(json.dumps(run(ROOT,write=args.write)));return 0
    except (c.CatalogError,OSError) as error:print(json.dumps(dict(status='failed',code=str(error) if isinstance(error,c.CatalogError) else 'fortinet_io_failed')));return 1
if __name__=='__main__':sys.exit(main())
